import {normalizePreparation,preparationSummary,requirementState,requirementSignature,runOfShow,challengeQuestions,preparationReport,sectionNames} from './preparation.mjs?v=ai-1.0';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let api={},view='map';
export function initPreparation(options){api=options;}
const p=()=>api.project();
const data=()=>p().preparation=normalizePreparation(p().preparation);
const options=(selected='problem')=>Object.entries(sectionNames).map(([k,v])=>`<option value="${k}" ${k===selected?'selected':''}>${v}</option>`).join('');
const time=n=>`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;
function mapView(d){return `<div class="prep-split"><section><div class="prep-section-title"><span>01 / REQUIREMENTS → YOUR STORY</span><h3>Every requirement.<br><em>A place in your pitch.</em></h3><p>Paste the current organizer wording, keep its source, and connect it to a slide. Your review is invalidated when that slide or requirement changes.</p></div>${d.requirements.length?d.requirements.map(r=>`<article class="requirement-card"><div><span class="pill ${requirementState(r,p())==='Reviewed by you'?'':'amber'}">${esc(requirementState(r,p()))}</span><small>${esc(sectionNames[r.section])} · ${r.weight?r.weight+'% rubric weight':'Weight not supplied'}</small></div><h4>${esc(r.title)}</h4><blockquote>${esc(r.quote||'Organizer wording not supplied.')}</blockquote><p class="requirement-source">Source: ${esc(r.source||'Missing')}</p><details><summary>Read your mapped slide</summary><p>${esc(p()[r.section]||'This section is empty.')}</p></details><div class="toolbar"><button class="btn small" data-prep-review="${esc(r.id)}" ${!r.source||!r.quote||!p()[r.section]?'disabled':''}>I reviewed this mapping ✓</button><button class="btn text small" data-prep-edit="${esc(r.id)}">Edit requirement</button><button class="btn text small" data-prep-story="${r.section}">Open slide ↗</button></div></article>`).join(''):'<div class="prep-empty"><span>↳</span><h3>The rubric is your starting point.</h3><p>Add the first requirement from your organizer. We’ll keep its wording beside the slide that addresses it.</p></div>'}</section><aside class="panel"><div class="eyebrow">FROM THE ORGANIZER</div><h3>Add a requirement.</h3><form id="prep-requirement"><input name="id" type="hidden"><div class="field"><label for="req-title">Requirement or judging criterion</label><input id="req-title" name="title" required maxlength="180" placeholder="e.g. Demonstrate technical feasibility"></div><div class="field"><label for="req-quote">Exact organizer wording</label><textarea id="req-quote" name="quote" maxlength="1600" required rows="4" placeholder="Paste the relevant rule or criterion…"></textarea></div><div class="field"><label for="req-source">Source URL or document and page</label><input id="req-source" name="source" maxlength="1000" required placeholder="Official rules PDF, page 4"></div><div class="field-row"><div class="field"><label for="req-section">Mapped slide</label><select id="req-section" name="section">${options()}</select></div><div class="field"><label for="req-weight">Weight % · optional</label><input id="req-weight" name="weight" type="number" min="0" max="100" step="1" placeholder="If published"></div></div><button class="btn primary" type="submit">Save requirement ↗</button><p class="hint">Up to 20 requirements. We do not invent a rubric or verify the pasted source.</p></form></aside></div>`;}
function teamView(d){return `<div class="prep-split"><section><div class="prep-section-title"><span>02 / A PLAN YOUR TEAM CAN USE</span><h3>Give every next step<br><em>an owner.</em></h3><p>A local task board for the work before the pitch. Export the workbook to hand it to teammates; changes do not sync between devices.</p></div>${d.tasks.map(t=>`<label class="prep-task"><input type="checkbox" data-prep-task="${esc(t.id)}" ${t.done?'checked':''}><span><strong>${esc(t.title)}</strong><small>${esc(t.owner||'Unassigned')} · ${esc(t.due||'No date')}</small></span><b>${t.done?'Done':'To do'}</b></label>`).join('')||'<div class="prep-empty"><h3>A clear next step beats a long wish list.</h3><p>Start with the biggest gap in the event rules, evidence, or demo.</p></div>'}<button class="btn" data-prep-seed>Add missing preparation tasks ↗</button></section><aside class="panel"><h3>One useful next step.</h3><form id="prep-task-form"><div class="field"><label for="task-title">Task</label><input id="task-title" name="title" maxlength="180" required placeholder="Test the demo without Wi-Fi"></div><div class="field"><label for="task-owner">Owner</label><input id="task-owner" name="owner" maxlength="80" placeholder="Name or role"></div><div class="field"><label for="task-due">Due date</label><input id="task-due" name="due" type="date"></div><button class="btn primary" type="submit">Add task +</button></form><p class="hint">Up to 30 tasks. No messages or invitations are sent.</p></aside></div>`;}
function rehearsalView(d){return `<div class="prep-section-title"><span>03 / EVERY SECOND HAS A JOB</span><h3>A pitch with rhythm.<br><em>A team with a plan.</em></h3><p>Suggested timing across your six story sections. Speaking estimates use 130 words/minute; practise to find your actual pace.</p></div><form id="prep-rehearsal"><div class="prep-time-control"><label for="prep-duration">Total pitch time</label><select id="prep-duration" name="duration">${[60,120,180,300,600].map(n=>`<option value="${n}" ${d.duration===n?'selected':''}>${n/60} minute${n===60?'':'s'}</option>`).join('')}</select><button class="btn primary" type="submit">Save speaking plan ✓</button></div><div class="run-grid">${runOfShow(p()).map(s=>`<article class="run-card"><div><strong>${time(s.start)}—${time(s.end)}</strong><span>${s.duration}s</span></div><h4>${s.title}</h4><label for="speaker-${s.key}">Speaker</label><input id="speaker-${s.key}" name="speaker-${s.key}" maxlength="80" value="${esc(s.speaker)}" placeholder="Assign a teammate"><p class="${s.over?'inline-error':'subtle'}">${s.words} words · ≈ ${s.estimated}s${s.over?' · shorten for this slot':''}</p><details><summary>Talking points</summary><p>${esc(s.script||'Add speaker notes in the story studio.')}</p></details></article>`).join('')}</div><div class="prep-split prep-demo"><div class="field"><label for="prep-demo">The one thing your demo will show</label><textarea id="prep-demo" name="demo" maxlength="1600" rows="4" placeholder="Describe the working interaction, starting state, and expected result.">${esc(d.demo)}</textarea></div><div class="field"><label for="prep-fallback">If the demo fails, what will you show?</label><textarea id="prep-fallback" name="fallback" maxlength="1600" rows="4" placeholder="A recording, screenshots, or a walkthrough. Say which parts are actually built.">${esc(d.fallback)}</textarea></div></div></form><div class="prep-review-heading"><h3>Questions worth practising.</h3><button class="btn" data-quick="questions">Open rehearsal timer ↗</button></div><div class="prep-question-grid">${challengeQuestions(p()).map(q=>`<details class="prep-question"><summary>${esc(q.question)}</summary><small>${esc(sectionNames[q.section])} / context supplied by you</small><p>${esc(q.context)}</p><button class="btn text small" data-prep-story="${q.section}">Work on this answer ↗</button></details>`).join('')}</div><p class="hint">These questions come from your mapped requirements and fixed preparation prompts. No AI jury has run.</p>`;}
function handoffView(d){const s=preparationSummary(p());return `<div class="prep-section-title"><span>04 / A HANDOFF WITH NOTHING HIDDEN</span><h3>Bring the whole story.<br><em>And the work behind it.</em></h3><p>Keep mentor feedback and submission details beside the draft. Download a workbook with your requirement map, tasks, timed script, questions, and feedback.</p></div><div class="handoff-band"><div><strong>${s.reviewed}/${s.requirements}</strong><span>mappings reviewed by you</span></div><div><strong>${s.done}/${s.tasks}</strong><span>tasks completed</span></div><div><strong>${s.feedback}</strong><span>open feedback notes</span></div><button class="btn primary" data-prep-download>Download preparation workbook ↓</button></div><div class="prep-split"><section class="panel"><h3>A second pair of eyes.</h3><form id="prep-feedback"><div class="field-row"><div class="field"><label for="feedback-author">Reviewer · optional</label><input id="feedback-author" name="author" maxlength="80"></div><div class="field"><label for="feedback-section">Slide</label><select id="feedback-section" name="section">${options()}</select></div></div><div class="field"><label for="feedback-note">Feedback or a question to resolve</label><textarea id="feedback-note" name="note" maxlength="1600" rows="3" required></textarea></div><button class="btn" type="submit">Save feedback +</button></form>${d.feedback.map(f=>`<label class="feedback-note"><input type="checkbox" data-prep-feedback="${esc(f.id)}" ${f.done?'checked':''}><span><small>${esc(f.author||'Reviewer')} · ${sectionNames[f.section]} · ${f.done?'Resolved':'Open'}</small><p>${esc(f.note)}</p></span></label>`).join('')}<p class="hint">Feedback is entered on this device. No public review link or cloud sharing is created.</p></section><aside class="panel"><h3>Keep the final details.</h3><form id="prep-submission"><div class="field"><label for="prep-portal">Official submission portal URL</label><input id="prep-portal" name="portal" type="url" maxlength="1000" value="${esc(d.portal)}" placeholder="https://…"></div><div class="field"><label for="prep-receipt">Receipt or submission reference</label><textarea id="prep-receipt" name="receipt" maxlength="1000" rows="3" placeholder="Record this after submitting on the official portal.">${esc(d.receipt)}</textarea></div><button class="btn" type="submit">Save submission record ✓</button></form><p class="hint">Saving a reference does not submit your project. Avoid storing passwords or private access tokens.</p><button class="btn primary" data-quick="exports">Review and export your files ↗</button></aside></div>`;}
export function preparationHub(){const d=data(),s=preparationSummary(p());return `<section class="prep-hero"><div><div class="eyebrow">YOUR PITCH / ALL THE MOVING PARTS</div><h2>One idea.<br><em>A whole team behind it.</em></h2><p>Connect the rules to the story, the story to the proof,<br>and the people to the moment.</p></div><div class="prep-orbit" aria-hidden="true"><span>CONTEXT</span><b>YOU<br>ARE HERE.</b><span>STORY · PROOF · DELIVERY</span><i>✳</i></div></section><nav class="prep-nav" aria-label="Preparation stages">${[['map','Requirements',s.reviewed+'/'+s.requirements],['team','Team plan',s.done+'/'+s.tasks],['rehearsal','Speaking plan',time(d.duration)],['handoff','Review & handoff',s.feedback+' open']].map(([k,t,n],i)=>`<button data-prep-view="${k}" aria-pressed="${view===k}"><span>0${i+1}</span><strong>${t}</strong><small>${n}</small></button>`).join('')}</nav><div class="prep-body">${view==='map'?mapView(d):view==='team'?teamView(d):view==='rehearsal'?rehearsalView(d):handoffView(d)}</div>`;}
function uid(){return crypto.randomUUID();}
async function commit(){p().preparation=normalizePreparation(p().preparation);await api.save();api.render();}
document.addEventListener('submit',async e=>{if(!['prep-requirement','prep-task-form','prep-rehearsal','prep-feedback','prep-submission'].includes(e.target.getAttribute('id')))return;e.preventDefault();const d=data(),values=Object.fromEntries(new FormData(e.target));try{if(e.target.getAttribute('id')==='prep-requirement'){const at=d.requirements.findIndex(r=>r.id===values.id);if(at<0&&d.requirements.length>=20)return api.toast('You can map up to 20 requirements.');const value={...values,id:values.id||uid(),reviewed:''};if(at<0)d.requirements.push(value);else d.requirements[at]=value;}if(e.target.getAttribute('id')==='prep-task-form'){if(d.tasks.length>=30)return api.toast('This plan already has 30 tasks.');d.tasks.push({...values,id:uid(),done:false});}if(e.target.getAttribute('id')==='prep-rehearsal'){d.duration=Number(values.duration);d.demo=values.demo;d.fallback=values.fallback;for(const k of Object.keys(sectionNames))d.speakers[k]=values['speaker-'+k];}if(e.target.getAttribute('id')==='prep-feedback'){if(d.feedback.length>=20)return api.toast('This project already has 20 feedback notes.');d.feedback.push({...values,id:uid(),done:false,at:new Date().toISOString()});}if(e.target.getAttribute('id')==='prep-submission'){d.portal=values.portal;d.receipt=values.receipt;}await commit();api.toast('Preparation saved on this device.');}catch{api.toast('Could not save. Export a backup before closing.');}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-prep-view],[data-prep-review],[data-prep-edit],[data-prep-story],[data-prep-download],[data-prep-seed]');if(!b||!p())return;const d=data();if(b.dataset.prepView){view=b.dataset.prepView;api.render();document.querySelector(`[data-prep-view="${view}"]`)?.focus({preventScroll:true});}else if(b.dataset.prepReview){const r=d.requirements.find(x=>x.id===b.dataset.prepReview);if(r&&r.source&&r.quote&&p()[r.section]){r.reviewed=requirementSignature(r,p());await commit();}}else if(b.dataset.prepEdit){const r=d.requirements.find(x=>x.id===b.dataset.prepEdit);if(r){const form=document.querySelector('#prep-requirement');for(const key of ['id','title','quote','source','section','weight'])form.elements[key].value=r[key];form.elements.title.focus();}}else if(b.dataset.prepStory){api.story(b.dataset.prepStory);}else if(b.hasAttribute('data-prep-download')){api.download(preparationReport(p()),p().name);}else if(b.hasAttribute('data-prep-seed')){const titles=[...(!p().confirmed?['Review the current organizer rules']:[]),...(!p().evidence.length?['Collect a real source for the evidence slide']:[]),...(!d.fallback?['Prepare a demo fallback']:[]),...(!p().rehearsals.length?['Run one timed rehearsal']:[]),'Open the exported files and inspect the final layout'];for(const title of titles)if(d.tasks.length<30&&!d.tasks.some(t=>t.title===title))d.tasks.push({id:uid(),title,owner:'',due:p().deadline,done:false});await commit();}});
document.addEventListener('change',async e=>{if(!p())return;const d=data();if(e.target.dataset.prepTask){const t=d.tasks.find(t=>t.id===e.target.dataset.prepTask);if(t){t.done=e.target.checked;await commit();}}if(e.target.dataset.prepFeedback){const f=d.feedback.find(f=>f.id===e.target.dataset.prepFeedback);if(f){f.done=e.target.checked;await commit();}}});
